//! VIA purpose-specific detail selection. Adequate refs/evidence/records need no compose call.
use super::sources::*;use crate::context::Context;use serde_json::{json,Value};
fn plan_capsule(plan:&Value,available:&[Value],record:&Value,sources:&Sources)->Value{
 let refs=array(&plan["references"]);let blocks:Vec<Value>=array(&record["blocks"]).into_iter().filter(|b|array(&plan["selected_record_blocks"]).contains(&b["block_id"])&&valid_block(b,sources)).collect();
 let mut selected=Vec::new();for span in array(&plan["selected_evidence_spans"]){if let Some(p)=available.iter().find(|p|valid_span(p,sources)&&contained(&span,p)){let base=p["start_line"].as_u64().unwrap();let lo=span["start_line"].as_u64().unwrap();let hi=span["end_line"].as_u64().unwrap();let mut q=span;q["text"]=json!(p["text"].as_str().unwrap().lines().skip((lo-base)as usize).take((hi-lo+1)as usize).collect::<Vec<_>>().join("\n"));selected.push(q);}}
 json!({"summary":plan["summary"],"references":refs,"passages":selected,"record_blocks":blocks,"unknowns":plan["unknowns"]})
}
pub fn build(ctx:&mut Context,variant:&str,mandatory:&Value,sources:&Sources,available:&[Value],record:&Value)->Result<Value,String>{
 if variant=="C"{return Ok(Value::Null);}
 let payload=json!({"instruction":"Select a sufficient purpose-specific portable handoff. Return JSON {mode:'DIRECT'|'READ',summary:string,references:[{source_id:string,revision:number,start_line:number,end_line:number}],selected_evidence_spans:[{source_id:string,revision:number,start_line:number,end_line:number}],selected_record_blocks:[string],reads:[{source_id:string,start_line:number,end_line:number}],unknowns:[string]}. DIRECT may transmit adequate current source-span references for large artifacts or already acquired source evidence; it does NOT require a new original read or new composed explanation. The receiver can read valid references. If valid supplied work-record blocks already suffice, select them DIRECT without redundant freshness reads (host checks currentness). Select original READ only when current purpose requires missing/uncertain semantic detail that VIA must inspect. Metadata is not facts and cannot ground an explanation. Do not invent source facts, change mandatory conditions, add domain plans or broaden actions. Empty evidence plus empty references is insufficient.","input":{"mandatory":mandatory,"manifest":catalog(sources),"actual_common_evidence":available,"work_record":if variant=="B"{record.clone()}else{Value::Null},"variant":variant},"max_tokens":1600});
 let stage=if variant=="B"{"dp05_extract_record"}else{"dp05_select_handoff_details"};let mut plan=ctx.call(stage,&payload)?;
 let mut capsule=plan_capsule(&plan,available,record,sources);
 if plan["mode"].as_str()!=Some("READ")&&capsule_valid(&capsule,sources){ctx.event("HANDOFF_BUILD_BRANCH",&json!({"branch":"DIRECT_VALID_REFERENCES_OR_AVAILABLE_EVIDENCE_OR_RECORD","variant":variant,"selected_record_blocks":plan["selected_record_blocks"]}));return Ok(capsule);}
 if array(&plan["reads"]).is_empty(){let mut repair=payload.clone();repair["input"]["rejected_plan"]=plan.clone();repair["input"]["repair_reason"]=json!("No valid direct capsule and no original reads. Return adequate refs/available blocks or actual bounded reads.");plan=ctx.call("dp05_repair_handoff_selection",&repair)?;capsule=plan_capsule(&plan,available,record,sources);if plan["mode"].as_str()!=Some("READ")&&capsule_valid(&capsule,sources){return Ok(capsule);}}
 let(passages,denied)=selected_reads(ctx,&plan["reads"],sources,"VIA_COMPOSER");if passages.is_empty(){return Err(format!("HANDOFF_DETAILS_UNAVAILABLE {}",json!(denied)));}
 let chosen=array(&capsule["record_blocks"]);let explanation=ctx.call("dp05_compose_capsule",&json!({"instruction":"Compose a compact purpose-specific explanation from ONLY actual supplied passages and valid work-record blocks. Return JSON {summary:string,unknowns:[string]}. Preserve caveats and mandatory constraints. No new domain plan, guessed facts or broadened actions. Exact original passages and source spans will be attached by the host; do not invent or rewrite their provenance.","input":{"mandatory":mandatory,"actual_passages":passages,"selected_record_blocks":chosen,"denials":denied},"max_tokens":1200}))?;
 let c=json!({"summary":explanation["summary"],"passages":passages,"record_blocks":chosen,"references":plan["references"],"unknowns":explanation["unknowns"]});ctx.event("HANDOFF_BUILD_BRANCH",&json!({"branch":"READ_AND_PURPOSE_COMPOSE","variant":variant,"denials":denied}));if capsule_valid(&c,sources){Ok(c)}else{Err("INVALID_CAPSULE_CURRENT_PROVENANCE".into())}
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn adequate_reference_direct_capsule_has_no_text_requirement(){let mut s=Sources::new();s.insert("x".into(),json!({"id":"x","revision":1,"allowed_lines":[1,80]}));let c=plan_capsule(&json!({"references":[{"source_id":"x","revision":1,"start_line":10,"end_line":12}]}),&[],&Value::Null,&s);assert!(capsule_valid(&c,&s));assert!(capsule_evidence(&c).is_empty());}
 #[test]fn sufficient_record_can_be_extracted_directly(){let mut s=Sources::new();s.insert("x".into(),json!({"id":"x","revision":1,"allowed_lines":[1,2]}));let p=json!({"source_id":"x","revision":1,"start_line":1,"end_line":2,"text":"Existing actual evidence."});let r=json!({"blocks":[{"block_id":"b","explanation":"Existing result.","source_spans":[p],"supporting_passages":[p]}]});let c=plan_capsule(&json!({"selected_record_blocks":["b"]}),&[],&r,&s);assert!(capsule_valid(&c,&s));assert_eq!(capsule_evidence(&c).len(),1);}
}
